/* @lc app=leetcode id=855 lang=kotlin */ class ExamRoom(val n: Int, val s: java.util.TreeSet<Int> = java.util.TreeSet(), val pq: java.util.PriorityQueue<IntArray> = java.util.PriorityQueue<IntArray>(compareBy<IntArray> { -it[3] }.thenBy { it[2] }).also { it.add(intArrayOf(-1, n, 0, Int.MAX_VALUE)) }) { fun push(l: Int, r: Int) = if (l < 0 && r > 0 || r >= n && l < n - 1 || l >= 0 && r < n && r - l >= 2) pq.add(if (l < 0) intArrayOf(l, r, 0, r) else if (r >= n) intArrayOf(l, r, n - 1, n - 1 - l) else intArrayOf(l, r, (l + r) / 2, (r - l) / 2)) else false fun seat(): Int = generateSequence { pq.poll() }.first { g -> (g[0] < 0 || s.contains(g[0])) && (if (g[0] < 0) (if (s.isEmpty()) n else s.first()) else (s.higher(g[0]) ?: n)) == g[1] }.let { g -> g[2].also { s.add(it) }.also { push(g[0], it) }.also { push(it, g[1]) } } fun leave(p: Int) { if (s.remove(p)) push(s.lower(p) ?: -1, s.higher(p) ?: n) } }